import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static int nextInt() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        int r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n];
        int even = 0;
        for (int i = 0; i < n; i++) { a[i] = nextInt(); if (a[i] % 2 == 0) even++; }
        // Odd numbers inside the first `even` slots must each be swapped out.
        long ans = 0;
        for (int i = 0; i < even; i++) ans += a[i] % 2;
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	return n
}

func main() {
	n := readInt()
	a := make([]int, n)
	even := 0
	for i := range a {
		a[i] = readInt()
		if a[i]%2 == 0 {
			even++
		}
	}
	// Odd numbers inside the first `even` slots must each be swapped out.
	ans := 0
	for i := 0; i < even; i++ {
		ans += a[i] % 2
	}
	fmt.Println(ans)
}
